/*
 * Checks that the .bat files really carry the CURRENT guard and installer.
 *
 *   node tools/verify-bats-embed.js
 *
 * The bats are generated by tools/build-mma-bats.js, which base64-embeds both
 * payloads. It is easy to change the guard and forget to rebuild, and the bats
 * then silently install a stale script. This decodes what is actually inside
 * each bat and compares it byte for byte with the sources.
 */
const fs = require('fs');
const path = require('path');
const { TOSU_DISCOVERY_SOURCE } = require('./tosu-discovery-source');

const root = path.join(__dirname, '..');

/* the embedded installer is the tosu-discovery source prepended to the CLI, so
   the bats can find the analyser folder on their own */
const installerSource =
    TOSU_DISCOVERY_SOURCE +
    '\n' +
    fs.readFileSync(path.join(__dirname, 'mma-guard-cli.js'), 'utf8');
const guardSource = fs.readFileSync(
    path.join(root, 'mma-guard', 'mma-visibility-guard.js'),
    'utf8'
);

const BATS = ['INSTALL.bat', 'UNINSTALL.bat', 'CHECK.bat'];

let failures = 0;

function check(ok, label, detail) {
    if (!ok) failures++;
    console.log(
        (ok ? '  OK    ' : '  FAIL  ') + label + (detail ? '   [' + detail + ']' : '')
    );
}

/* pull every [Convert]::FromBase64String('...') payload out of a bat */
function embedded(batText) {
    const found = [];
    const re = /FromBase64String\('([A-Za-z0-9+/=]+)'\)/g;
    let match;
    while ((match = re.exec(batText)) !== null) {
        found.push(Buffer.from(match[1], 'base64').toString('utf8'));
    }
    return found;
}

console.log('installed guard source : ' + guardSource.length + ' bytes');
console.log('installer source       : ' + installerSource.length + ' bytes');
console.log('');

/* the guard must carry the menu fix, or the bats would install the flickering one */
check(
    guardSource.includes('inMenu'),
    'the guard source mirrors the analyser menu rule'
);
check(
    guardSource.includes('reasserts'),
    'the guard source separates fixes from reasserts'
);

BATS.forEach((name) => {
    const file = path.join(root, name);
    if (!fs.existsSync(file)) {
        check(false, name + ' exists');
        return;
    }

    const text = fs.readFileSync(file, 'latin1');
    const payloads = embedded(text);

    console.log('');
    console.log(name + '  ' + text.length + ' bytes, ' + payloads.length + ' embedded payload(s)');

    check(payloads.length === 2, 'carries two payloads (installer + guard)');

    if (payloads.length !== 2) return;

    /* order in the generated file: installer first, then guard */
    const [installer, guard] = payloads;

    check(
        installer === installerSource,
        'embedded installer matches tools/mma-guard-cli.js',
        installer === installerSource
            ? 'identical'
            : 'embedded ' + installer.length + ' vs source ' + installerSource.length
    );
    check(
        guard === guardSource,
        'embedded guard matches mma-guard/mma-visibility-guard.js',
        guard === guardSource
            ? 'identical'
            : 'embedded ' + guard.length + ' vs source ' + guardSource.length +
              ' - run: node tools/build-mma-bats.js'
    );
    check(
        guard.includes('inMenu'),
        'embedded guard has the menu fix',
        guard.includes('inMenu') ? 'yes' : 'NO - stale'
    );
});

console.log('');
if (failures === 0) {
    console.log('all bats carry the current payloads');
} else {
    console.log(failures + ' FAILED - rebuild with: node tools/build-mma-bats.js');
}
process.exit(failures === 0 ? 0 : 1);
